import{_ as p,a0 as o,w as n,s,ao as i,I as m,x as d,a1 as t,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何使用linux程序mdadm创建软件RAID1软阵列 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用linux程序mdadm创建软件RAID1软阵列 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用linux程序mdadm创建软件RAID1软阵列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用linux程序mdadm创建软件RAID1软阵列 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20140917 How to create a software RAID-1 array with mdadm on Linux","title":"如何使用linux程序mdadm创建软件RAID1软阵列","tag":"201502","desc":""},"relativePath":"201502/20140917 How to create a software RAID-1 array with mdadm on Linux.md","filePath":"[post].md"}'),l={name:"201502/20140917 How to create a software RAID-1 array with mdadm on Linux.md"};function c(f,e,u,b,h,v){const a=o("Link");return n(),s("div",null,[e[13]||(e[13]=i(`<h1 id="如何使用linux程序mdadm创建软件raid1软阵列" tabindex="-1">如何使用linux程序mdadm创建软件RAID1软阵列 <a class="header-anchor" href="#如何使用linux程序mdadm创建软件raid1软阵列" aria-label="Permalink to “如何使用linux程序mdadm创建软件RAID1软阵列”">​</a></h1><p>磁盘冗余阵列(RAID)是将多个物理磁盘结合成一个逻辑磁盘的技术，该技术可以提高磁盘容错性能，提高磁盘的读写速度。根据数据存储的排列(如：条带存储，镜像存储，奇偶或者他们的组合)，定义了几个不同级别的RAID(RAID-0，RAID-1，RAID-5 等等)。磁盘阵列可以使用软件或者硬件方式实现。现代Linux操作系统中，基本的软件RAID功能是默认安装的。</p><p>本文中，我们将介绍软件方式构建RAID-1阵列(镜像阵列)，RAID-1将相同的数据写到不同的设备中。虽然可以使用同一个磁盘的两个分区实现RAID-1，但是如果磁盘坏了的话数据就都丢了，所以没什么意义。实际上，这也是为什么大多数RAID级别都使用多个物理磁盘提供冗余。当单盘失效后不影响整个阵列的运行，并且可以在线更换磁盘，最重要的是数据不会丢失。尽管如此，阵列不能取代外部存储的定期备份。</p><p>由于RAID-1阵列的大小是阵列中最小磁盘的大小，一般来说应该使用两个大小相同的磁盘来组建RAID-1。</p><h3 id="安装mdadm" tabindex="-1">安装mdadm <a class="header-anchor" href="#安装mdadm" aria-label="Permalink to “安装mdadm”">​</a></h3><p>我们将使用mdadm（简称多盘管理）工具创建、组装、管理和监控软件RAID-1。在诸如Fedora、CentOS、RHEL或者Arch Linux 的发行版中，mdadm是默认安装的。在基于Debian的发行版中，可以使用aptitude 或者 apt-get 安装mdadm。</p><h4 id="fedora-centos-或-rhel" tabindex="-1">Fedora, CentOS 或 RHEL <a class="header-anchor" href="#fedora-centos-或-rhel" aria-label="Permalink to “Fedora, CentOS 或 RHEL”">​</a></h4><p>由于adadm是预装的，所以我们只需要开启RAID守护服务，并将其配置成开机启动即可：</p><pre><code># systemctl start mdmonitor
# systemctl enable mdmonitor 
</code></pre><p>对于CentOS/RHEL 6系统，使用以下命令：</p><pre><code># service mdmonitor start
# chkconfig mdmonitor on 
</code></pre><h4 id="debian-ubuntu-或-linux-mint" tabindex="-1">Debian, Ubuntu 或 Linux Mint <a class="header-anchor" href="#debian-ubuntu-或-linux-mint" aria-label="Permalink to “Debian, Ubuntu 或 Linux Mint”">​</a></h4><p>在Debian或类Debian系统中，mdadm可以使用 <strong>aptitude 或者 apt-get</strong> 安装：</p><pre><code># aptitude install mdadm 
</code></pre><p>Ubuntu系统中，会要求配置Postfix MTA 以发送电子邮件通知。你可以跳过去。</p><p>Debian系统中，安装程序会显示以下解释信息，用来帮助我们去判断是否将根目录安装到RAID阵列中。下面的所有操作都有赖于这一步，所以应该仔细阅读他。</p><p><img src="https://farm4.staticflickr.com/3918/15220883382_c14eb95914_z.jpg" alt=""></p><p>我们不在根目录使用RAID-1，所以留空。</p><p><img src="https://farm6.staticflickr.com/5555/15198241896_29e08b977f.jpg" alt=""></p><p>提示是否开机启动阵列的时候，选择“是”。注意，这里需要往/etc/fstab 文件中添加一个条目使得系统启动的时候正确挂载阵列。</p><p><img src="https://farm4.staticflickr.com/3875/15220883342_2b1d689a0a_z.jpg" alt=""></p><h3 id="硬盘分区" tabindex="-1">硬盘分区 <a class="header-anchor" href="#硬盘分区" aria-label="Permalink to “硬盘分区”">​</a></h3><p>现在开始准备建立阵列需要的硬盘。这里插入两个8GB的usb磁盘，使用dmesg命令设备显示设备 /dev/sdb 和 /dev/sdc</p><pre><code># dmesg | less 
</code></pre><hr><p>[ 60.014863] sd 3:0:0:0: [sdb] 15826944 512-byte logical blocks: (8.10 GB/7.54 GiB) [ 75.066466] sd 4:0:0:0: [sdc] 15826944 512-byte logical blocks: (8.10 GB/7.54 GiB)</p><p>我们使用fdisk为每个磁盘建立一个大小为8G的主分区。以下步骤是如何在/dev/sdb上建立分区，假设次磁盘从未被分区(如果有其他分区的话，可以删掉)：</p><pre><code># fdisk /dev/sdb 
</code></pre><p>按p键输出现在的分区表：</p><p><img src="https://farm4.staticflickr.com/3883/15198241836_24625edcf3_z.jpg" alt=""></p><p>(如果有分区的话，可以使用 d 选项删除，w 选项应用更改)。</p><p>磁盘上没有分区，所以我们使用命令 [&#39;n&#39;] 创建一个主分区[&#39;p&#39;], 分配分区号为[&#39;1&#39;] 并且指定大小。你可以按回车使用默认值，或者输入一个你想设置的值。如下图：</p><p><img src="https://farm4.staticflickr.com/3875/15034475369_7e72fb9f2e_z.jpg" alt=""></p><p>用同样的方法为/dev/sdc 分区。</p><p>如果我们有两个不同容量的硬盘，比如 750GB 和 1TB的话，我们需要在每个磁盘上分出一个750GB的主分区，大盘剩下的空间可以用作他用，不加入磁盘阵列。</p><h3 id="创建-raid-1-阵列" tabindex="-1">创建 RAID-1 阵列 <a class="header-anchor" href="#创建-raid-1-阵列" aria-label="Permalink to “创建 RAID-1 阵列”">​</a></h3><p>磁盘分区完成后，我们可以使用以下命令创建 RAID-1 阵列：</p><pre><code># mdadm -Cv /dev/md0 -l1 -n2 /dev/sdb1 /dev/sdc1 
</code></pre><p>说明：</p><ul><li><strong>-Cv</strong>: 创建一个阵列并打印出详细信息。</li><li><strong>/dev/md0</strong>: 阵列名称。</li><li><strong>-l1</strong> (l as in &quot;level&quot;): 指定阵列类型为 RAID-1 。</li><li><strong>-n2</strong>: 指定我们将两个分区加入到阵列中去，分别为/dev/sdb1 和 /dev/sdc1</li></ul><p>以上命令和下面的等价:</p><pre><code> # mdadm --create --verbose /dev/md0 --level=1 --raid-devices=2 /dev/sdb1 /dev/sdc1 
</code></pre><p>如果你想在在磁盘失效时添加另外一个磁盘到阵列中，可以指定 &#39;--spare-devices=1 /dev/sdd1&#39; 到以上命令。</p><p>输入 “y” 继续创建阵列，回车：</p><p><img src="https://farm4.staticflickr.com/3894/15034569970_709bd51718.jpg" alt=""></p><p>可以使用以下命令查看进度：</p><pre><code> # cat /proc/mdstat 
</code></pre><p><img src="https://farm6.staticflickr.com/5565/15221267975_701b819e6d_z.jpg" alt=""></p><p>另外一个获取阵列信息的方法是：</p><pre><code># mdadm --query /dev/md0
# mdadm --detail /dev/md0 (or mdadm -D /dev/md0) 
</code></pre><p><img src="https://farm6.staticflickr.com/5583/15034683868_6c28564e5a_z.jpg" alt=""></p><p>&#39;mdadm -D&#39;命令提供的信息中，最重要就是阵列状态类。激活状态说明阵列正在进行读写操作。其他几个状态分别为：完成(读写完成)、降级(有一块磁盘失效或丢失)或者恢复中(一张新盘已插入，系统正在写入数据)。这几个状态涵盖了大多数情况。</p><h3 id="格式化或加载磁盘阵列" tabindex="-1">格式化或加载磁盘阵列 <a class="header-anchor" href="#格式化或加载磁盘阵列" aria-label="Permalink to “格式化或加载磁盘阵列”">​</a></h3><p>下一步就是格式化阵列了，本例中使用ext4格式：</p><pre><code> # mkfs.ext4 /dev/md0 
</code></pre><p><img src="https://farm4.staticflickr.com/3849/15034683838_01e34e7196_z.jpg" alt=""></p><p>现在可以加载阵列并验证其正常加载：</p><pre><code># mount /dev/md0 /mnt
# mount 
</code></pre><p><img src="https://farm6.staticflickr.com/5554/15034696167_c4fc907c8e_z.jpg" alt=""></p><h3 id="监控磁盘阵列" tabindex="-1">监控磁盘阵列 <a class="header-anchor" href="#监控磁盘阵列" aria-label="Permalink to “监控磁盘阵列”">​</a></h3><p>mdadm工具内置有磁盘阵列监控功能。当mdadm作为守护程序运行的时候(就像我们上文那样)，会周期性的检测阵列运行状态，将检测到的信息通过电子邮件或者系统日志报告上来。当然，也可以配置其在发生致命性错误的时候调用紧急命令。</p><p>mdadm默认会记录所有已知分区和阵列的事件，并将他们记录到 /var/log/syslog中。或者你可以在配置文件中(debian系统：/etc/mdadm/mdadm.conf ，红帽子系统：/etc/mdadm.conf )用以下格式指定监控设备或者阵列。如果mdadm.conf文件不存在，你可以创建一个。</p><pre><code>DEVICE /dev/sd[bcde]1 /dev/sd[ab]1
 
ARRAY /dev/md0 devices=/dev/sdb1,/dev/sdc1
ARRAY /dev/md1 devices=/dev/sdd1,/dev/sde1
.....
 
# optional email address to notify events
MAILADDR your@email.com
</code></pre><p>编辑完毕mdadm配置文件后，重启mdadm服务：</p><p>Debian系统，Ubuntu或者Linux Mint:</p><pre><code># service mdadm restart
</code></pre><p>Fedora, CentOS 或 RHEL 7:</p><pre><code># systemctl restart mdmonitor
</code></pre><p>CentOS或者RHEL 6:</p><pre><code># service mdmonitor restart 
</code></pre><h3 id="自动加载阵列" tabindex="-1">自动加载阵列 <a class="header-anchor" href="#自动加载阵列" aria-label="Permalink to “自动加载阵列”">​</a></h3><p>现在我们在/etc/fstab中加入条目使得系统启动的时候将阵列挂载到/mnt目录下：</p><pre><code># echo &quot;/dev/md0 /mnt ext4 defaults 0 2&quot; &lt;&lt; /etc/fstab 
</code></pre><p>为了验证挂载脚本工作正常，我们首先卸载阵列，重启mdadm，然后重新加载。可以看到/dev/md0已经安装我们添加到/etc/fstab中的条目加载了：</p><pre><code># umount /mnt
# service mdadm restart (on Debian, Ubuntu or Linux Mint)
or systemctl restart mdmonitor (on Fedora, CentOS/RHEL7)
or service mdmonitor restart (on CentOS/RHEL6)
# mount -a 
</code></pre><p><img src="https://farm6.staticflickr.com/5563/15218183681_63a10da704_z.jpg" alt=""></p><p>现在我们的阵列已经可以访问了，拷贝文件/etc/passwd到/mnt中测试一下：</p><p><img src="https://farm6.staticflickr.com/5593/15034475219_a3476aec0a_o.png" alt=""></p><p>Debian系统中，需要在/etc/default/mdadm 设置 AUTOSTART 变量为 true 才能使mdadm守护程序在开机时自动加载阵列：</p><pre><code>AUTOSTART=true
</code></pre><h3 id="模拟磁盘丢失故障" tabindex="-1">模拟磁盘丢失故障 <a class="header-anchor" href="#模拟磁盘丢失故障" aria-label="Permalink to “模拟磁盘丢失故障”">​</a></h3><p>我们将使用以下命令卸载磁盘来模拟磁盘故障。注意，在实际应用中，磁盘如果已经是故障状态了，不需要卸载。</p><p>首先，卸载阵列：</p><pre><code># umount /mnt 
</code></pre><p>现在注意每次执行命令后 &#39;mdadm -D /dev/md0&#39; 的输出。</p><pre><code># mdadm /dev/md0 --fail /dev/sdb1 #Marks /dev/sdb1 as faulty
# mdadm --remove /dev/md0 /dev/sdb1 #Removes /dev/sdb1 from the array
</code></pre><p>然后，如果你有个备用盘的话，重新添加一下：</p><pre><code> # mdadm /dev/md0 --add /dev/sdb1 
</code></pre><p>数据会被自动添加到备用盘 /dev/sdb1 上：</p><p><img src="https://farm4.staticflickr.com/3855/15221267875_dfc6af8804_z.jpg" alt=""></p><p>注意以上所述步骤只适合支持磁盘热拔插的系统，在不支持热拔插的系统中，还是得停止阵列并关机后更换备用盘：</p><pre><code># mdadm --stop /dev/md0
# shutdown -h now 
</code></pre><p>最后将新驱动器重新添加到阵列中：</p><pre><code># mdadm /dev/md0 --add /dev/sdb1
# mdadm --assemble /dev/md0 /dev/sdb1 /dev/sdc1 
</code></pre><p>希望本文对你有所帮助。</p><hr>`,96)),m("p",null,[e[1]||(e[1]=d("via: ",-1)),t(a,{href:"http://xmodulo.com/2014/09/create-software-raid1-array-mdadm-linux.html"},{default:r(()=>[...e[0]||(e[0]=[d("http://xmodulo.com/2014/09/create-software-raid1-array-mdadm-linux.html",-1)])]),_:1})]),m("p",null,[e[5]||(e[5]=d("作者：",-1)),t(a,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...e[2]||(e[2]=[d("Gabriel Cánepa",-1)])]),_:1}),e[6]||(e[6]=d(" 译者：",-1)),t(a,{href:"https://github.com/shipsw"},{default:r(()=>[...e[3]||(e[3]=[d("shipsw",-1)])]),_:1}),e[7]||(e[7]=d(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[d("wxy",-1)])]),_:1})]),m("p",null,[e[10]||(e[10]=d("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[d("LCTT",-1)])]),_:1}),e[11]||(e[11]=d(" 原创翻译，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[d("Linux中国",-1)])]),_:1}),e[12]||(e[12]=d(" 荣誉推出",-1))])])}const R=p(l,[["render",c]]);export{D as __pageData,R as default};
